import React, { useState } from 'react';
import { apiDangNhap } from '../api/goi_api';
// Nhớ bỏ file ảnh của bạn vào thư mục src/assets/ và đặt tên là background.jpg nhé
import bgImage from '../assets/background.jpg'; 

const DangNhap = () => {
    const [form, setForm] = useState({ ten: '', mk: '' });

    const handleLogin = async (e) => {
        e.preventDefault();
        try {
            // Gọi API đăng nhập
            await apiDangNhap({ 
                ten_dang_nhap: form.ten, 
                mat_khau: form.mk 
            });
            alert("Đăng nhập thành công!");
        } catch (error) {
            console.error(error);
            alert("Lỗi kết nối server hoặc sai tài khoản!");
        }
    };

    return (
        <div style={styles.container}>
            <div style={styles.loginBox}>

                {/* Cột trái: Banner tối màu */}
                <div style={styles.leftSide}>
                    <div style={styles.logoContainer}>
                        <span style={styles.icon}>🏬</span>
                        <h1 style={styles.brandName}>A&RMS</h1>
                    </div>
                    <div style={styles.welcomeText}>
                        <p style={styles.mainWelcome}>Chào mừng đã đến với A&RMS,</p>
                        <p style={styles.subWelcome}>Phần mềm quản lý căn hộ và khu dân cư!</p>
                    </div>
                </div>

                {/* Cột phải: Form nhập liệu */}
                <div style={styles.rightSide}>
                    <h2 style={styles.title}>Apartment & Resident Management System</h2>

                    <form onSubmit={handleLogin} style={styles.form}>
                        <div style={styles.inputGroup}>
                            <input 
                                type="text" 
                                placeholder="Tài khoản ..." 
                                style={styles.input}
                                onChange={(e) => setForm({...form, ten: e.target.value})}
                                required
                            />
                        </div>

                        <div style={styles.inputGroup}>
                            <input 
                                type="password" 
                                placeholder="Mật khẩu ..." 
                                style={styles.input}
                                onChange={(e) => setForm({...form, mk: e.target.value})}
                                required
                            />
                        </div>

                        <button type="submit" style={styles.loginBtn}>Đăng nhập</button>
                    </form>

                    <div style={styles.footer}>
                        <a href="#!" style={styles.registerLink}>Đăng ký tài khoản mới</a>
                    </div>
                </div>
            </div>
        </div>
    );
};

// Toàn bộ CSS chuẩn để "vừa code vừa xem"
const styles = {
    container: {
        height: '100vh',
        display: 'flex',
        justifyContent: 'center',
        alignItems: 'center',
        // Phần xử lý ảnh nền
        backgroundImage: `linear-gradient(rgba(0,0,0,0.5), rgba(0,0,0,0.5)), url(${bgImage})`,
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        fontFamily: "'Inter', 'Segoe UI', Tahoma, sans-serif",
    },
    loginBox: {
        display: 'flex',
        width: '880px',
        height: '480px',
        backgroundColor: 'rgba(255, 255, 255, 0.95)', // Hơi trong suốt nhẹ cho sang
        borderRadius: '20px',
        boxShadow: '0 25px 50px rgba(0,0,0,0.3)',
        overflow: 'hidden',
    },
    leftSide: {
        flex: 1,
        backgroundColor: '#1c1c1c', 
        padding: '50px',
        color: '#ffffff',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
    },
    logoContainer: {
        display: 'flex',
        alignItems: 'center',
        gap: '12px',
        marginBottom: '30px',
    },
    icon: { fontSize: '35px' },
    brandName: { 
        fontSize: '32px', 
        fontWeight: 'bold', 
        margin: 0, 
        letterSpacing: '1px' 
    },
    welcomeText: { lineHeight: '1.6' },
    mainWelcome: { fontSize: '18px', fontWeight: '600', marginBottom: '8px' },
    subWelcome: { fontSize: '14px', opacity: 0.8 },

    rightSide: {
        flex: 1.3,
        padding: '50px 60px',
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
    },
    title: {
        fontSize: '19px',
        color: '#444',
        textAlign: 'center',
        marginBottom: '40px',
        fontWeight: '500',
    },
    form: {
        display: 'flex',
        flexDirection: 'column',
        gap: '18px',
    },
    inputGroup: {
        width: '100%',
    },
    input: {
        width: '100%',
        padding: '14px 16px',
        borderRadius: '8px',
        border: '1px solid #ddd',
        fontSize: '15px',
        outline: 'none',
        boxSizing: 'border-box',
        backgroundColor: '#f9f9f9',
    },
    loginBtn: {
        padding: '14px',
        backgroundColor: '#4e342e', // Màu nâu giống ảnh của bạn
        color: '#fff',
        border: 'none',
        borderRadius: '8px',
        fontSize: '16px',
        fontWeight: 'bold',
        cursor: 'pointer',
        marginTop: '10px',
        transition: 'all 0.3s ease',
    },
    footer: {
        marginTop: '25px',
        textAlign: 'center',
    },
    registerLink: {
        color: '#2e7d32', // Màu xanh lá
        textDecoration: 'none',
        fontSize: '14px',
        fontWeight: '500',
    }
};

export default DangNhap;
